export default "import { VariableRefresh } from '@grafana/data';\nimport {\n  SceneFlexLayout,\n  SceneTimeRange,\n  SceneVariableSet,\n  TestVariable,\n  EmbeddedScene,\n  SceneFlexItem,\n  NestedScene,\n  SceneAppPage,\n  SceneAppPageState,\n  PanelBuilders,\n  VariableValueSelectors,\n  SceneTimePicker,\n} from '@grafana/scenes';\nimport { getEmbeddedSceneDefaults, getQueryRunnerWithRandomWalkQuery } from './utils';\n\nexport function getNestedScenesAndVariablesDemo(defaults: SceneAppPageState) {\n  return new SceneAppPage({\n    ...defaults,\n    $variables: new SceneVariableSet({\n      variables: [\n        new TestVariable({\n          name: 'server',\n          query: 'A.*',\n          value: 'server',\n          text: '',\n          delayMs: 2000,\n          options: [],\n        }),\n        new TestVariable({\n          name: 'notUsed',\n          query: 'A.$A.*',\n          value: 'server',\n          text: '',\n          delayMs: 5000,\n          options: [],\n        }),\n      ],\n    }),\n    controls: [new VariableValueSelectors({})],\n    tabs: [\n      new SceneAppPage({\n        title: 'Overview',\n        url: `${defaults.url}/overview`,\n        routePath: 'overview',\n        getScene: () => {\n          return new EmbeddedScene({\n            ...getEmbeddedSceneDefaults(),\n            $variables: new SceneVariableSet({\n              variables: [\n                new TestVariable({\n                  name: 'pod',\n                  query: 'A.$server.*',\n                  value: 'pod',\n                  delayMs: 2000,\n                  isMulti: true,\n                  text: '',\n                  options: [],\n                }),\n              ],\n            }),\n            body: new SceneFlexLayout({\n              direction: 'row',\n              children: [\n                new SceneFlexItem({\n                  body: new SceneFlexLayout({\n                    direction: 'column',\n                    children: [\n                      new SceneFlexItem({\n                        body: new SceneFlexLayout({\n                          children: [\n                            new SceneFlexItem({\n                              body: PanelBuilders.timeseries()\n                                .setTitle('handler: $handler')\n                                .setData(getQueryRunnerWithRandomWalkQuery({ alias: 'handler: $pod' }))\n                                .build(),\n                            }),\n                          ],\n                        }),\n                      }),\n                      new SceneFlexItem({\n                        body: getInnerScene('Inner scene1'),\n                      }),\n                    ],\n                  }),\n                }),\n              ],\n            }),\n            $timeRange: new SceneTimeRange(),\n          });\n        },\n      }),\n    ],\n  });\n}\n\nexport function getInnerScene(title: string) {\n  const scene = new NestedScene({\n    title: title,\n    canRemove: true,\n    canCollapse: true,\n    $variables: new SceneVariableSet({\n      variables: [\n        new TestVariable({\n          name: 'handler',\n          query: 'A.$server.$pod.*',\n          value: 'pod',\n          delayMs: 2000,\n          isMulti: true,\n          text: '',\n          options: [],\n          refresh: VariableRefresh.onTimeRangeChanged,\n        }),\n      ],\n    }),\n    body: new SceneFlexLayout({\n      direction: 'row',\n      children: [\n        new SceneFlexItem({\n          body: PanelBuilders.timeseries()\n            .setTitle('handler: $handler')\n            .setData(getQueryRunnerWithRandomWalkQuery({ alias: 'handler: $handler' }))\n            .build(),\n        }),\n      ],\n    }),\n    $timeRange: new SceneTimeRange(),\n    $data: getQueryRunnerWithRandomWalkQuery(),\n    controls: [new VariableValueSelectors({}), new SceneTimePicker({})],\n  });\n\n  return scene;\n}\n";